import { Platform } from 'react-native'
import messaging from '@react-native-firebase/messaging'
import RNVoipPushNotification from 'react-native-voip-push-notification'

// Imported lazily inside the function: auth.ts imports this file at module
// top, so a top-level `import { useAuthStore } from '@/store'` here would
// create a cycle and bind `useAuthStore` to undefined at call time.
const getAuthStore = () => {
  const auth = require('@/store/auth')
  return auth ? auth.useAuthStore : null
}

export const registerNotificationToken = async () => {
  const useAuthStore = getAuthStore()

  if (!useAuthStore) {
    console.error('Auth store not found during token registration')
    return
  }

  // Register just FCM
  if (Platform.OS === 'android') {
    try {
      const fcmToken = await messaging().getToken()
      await useAuthStore.getState().editUser({ fcm_token: fcmToken, device: Platform.OS })
    } catch (error) {
      console.error('Failed to register Android push token:', error)
    }
  }

  // Register both VoIP (for calls notifs) and FCM (for everything else)
  if (Platform.OS === 'ios') {
    try {
      RNVoipPushNotification.addEventListener('register', async voipToken => {
        await useAuthStore.getState().editUser({ voip_token: voipToken, device: Platform.OS })
        RNVoipPushNotification.removeEventListener('register')
      })
      RNVoipPushNotification.registerVoipToken()

      const fcmToken = await messaging().getToken()
      await useAuthStore.getState().editUser({ fcm_token: fcmToken, device: Platform.OS })
    } catch (error) {
      console.error('Failed to register iOS VoIP token:', error)
    }
  }
}

