import { Platform } from 'react-native'
import messaging, { FirebaseMessagingTypes } from '@react-native-firebase/messaging'
import RNVoipPushNotification from 'react-native-voip-push-notification'

import { useCallsStore } from '@/store/calls'
import { useContactsStore } from '@/store/contacts'

export function setFirebaseNotificationService() {
  const firebaseMessageHandler = async (message: FirebaseMessagingTypes.RemoteMessage) => {
    if (!message?.data?.type || !message || !message.data) {
      console.warn('Received message without notification type')
      return
    }
    const data = message.data
    console.log('fb notif', data)

    const notificationType = message.data.type

    switch (notificationType) {
      // CALLS
      case 'incoming_call':
        if (Platform.OS === 'android') {
          useCallsStore.getState().handleIncomingCall(data)
        }
        break
      case 'call_rejected':
        // you're the caller and call was rejected by the callee
        useCallsStore.getState().handleCallRejected(data)
        break
      case 'call_cancelled':
        // you're the callee and call was cancelled by the caller before you answered it
        useCallsStore.getState().handleCallCancelled(data)
        break

      // FRIENDS
      case 'friend_available':
        await useContactsStore.getState().handleFriendAvailable(data)
        break
      case 'friend_unavailable':
        await useContactsStore.getState().handleFriendUnavailable(data)
        break

      default:
        console.warn('Unknown notification type:', notificationType)
        break
    }
  }

  // Register handlers for both background and foreground events
  messaging().setBackgroundMessageHandler(firebaseMessageHandler)
  messaging().onMessage(firebaseMessageHandler)
}

