import logging
from typing import Any, Optional

import httpx

from app.core.config import settings


logger = logging.getLogger(__name__)


class VoIPNotificationService:
    """Send VoIP push notifications via Apple APNs."""

    SANDBOX_URL = "https://api.sandbox.push.apple.com/3/device"
    PRODUCTION_URL = "https://api.push.apple.com/3/device"

    def __init__(
        self,
        cert_path: Optional[str] = None,
        bundle_id: Optional[str] = None,
        use_sandbox: Optional[bool] = None,
        timeout: float = 30.0,
    ):
        self.cert_path = cert_path or settings.voip_cert_path
        self.bundle_id = bundle_id or settings.voip_bundle_id
        self.use_sandbox = settings.voip_use_sandbox if use_sandbox is None else use_sandbox
        self.timeout = timeout

    def _base_url(self) -> str:
        return self.SANDBOX_URL if self.use_sandbox else self.PRODUCTION_URL

    def _headers(self) -> dict[str, str]:
        return {
            "apns-topic": f"{self.bundle_id}.voip",
            "apns-push-type": "voip",
            "apns-priority": "10",
            "content-type": "application/json",
        }

    @staticmethod
    def _payload(stream_data: dict[str, Any]) -> dict[str, Any]:
        return {"aps": {"content-available": 1}, "stream": stream_data}

    def send_notification(
        self, device_token: str, stream_data: dict[str, Any]
    ) -> tuple[bool, dict[str, Any]]:
        url = f"{self._base_url()}/{device_token}"
        cert = (self.cert_path, self.cert_path)

        try:
            with httpx.Client(http2=True, cert=cert, timeout=self.timeout) as client:
                response = client.post(url, headers=self._headers(), json=self._payload(stream_data))
                success = response.status_code == 200
                resp = {
                    "status_code": response.status_code,
                    "response_text": response.text,
                    "success": success,
                }
                if success:
                    logger.info(f"VoIP notification sent to {device_token[:8]}...")
                else:
                    logger.error(f"VoIP send failed status={response.status_code}: {response.text}")
                return success, resp
        except Exception as e:
            logger.error(f"Error sending VoIP notification: {e}")
            return False, {"error": str(e), "success": False}

