import json
import logging
import os
from typing import Any, Optional

import firebase_admin
from firebase_admin import credentials, messaging

from app.core.config import settings


logger = logging.getLogger(__name__)


class FirebaseNotificationService:
    """Send Firebase push notifications via a single Admin SDK app instance."""

    def __init__(self):
        self.app: Optional[firebase_admin.App] = None
        self._initialize()

    def _initialize(self) -> None:
        path = settings.firebase_credentials
        name = "callme_app"

        existing_app_names = {app.name for app in firebase_admin._apps.values()}
        try:
            if name in existing_app_names:
                self.app = firebase_admin.get_app(name)
                return
            if not os.path.exists(path):
                logger.warning(f"Firebase service account file not found: {path}")
                return
            cred = credentials.Certificate(path)
            self.app = firebase_admin.initialize_app(cred, name=name)
            logger.info("Initialized Firebase app")
        except Exception as e:
            logger.error(f"Error initializing Firebase app: {e}")

    @staticmethod
    def _stringify_data(data: Optional[dict[str, Any]]) -> Optional[dict[str, str]]:
        if not data:
            return None
        out: dict[str, str] = {}
        for k, v in data.items():
            if isinstance(v, (dict, list)):
                out[str(k)] = json.dumps(v)
            else:
                out[str(k)] = str(v)
        return out

    def send_notification(
        self,
        device_token: str,
        title: Optional[str] = None,
        body: Optional[str] = None,
        data: Optional[dict[str, Any]] = None,
    ) -> dict[str, Any]:
        if self.app is None:
            return {"success": False, "error": "Firebase app not initialized"}

        try:
            string_data = self._stringify_data(data)
            if title is not None or body is not None:
                message = messaging.Message(
                    notification=messaging.Notification(title=title or "", body=body or ""),
                    token=device_token,
                    data=string_data,
                )
            else:
                message = messaging.Message(token=device_token, data=string_data)

            response = messaging.send(message, app=self.app)
            return {
                "success": True,
                "message_id": response,
                "silent": title is None and body is None,
            }
        except Exception as e:
            logger.error(f"Firebase send failed: {e}")
            return {"success": False, "error": str(e)}

